package hu.synostream.android;
import org.junit.*;
import static org.junit.Assert.*;

import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.io.*;
public class NasClientTest {
 final java.util.concurrent.CountDownLatch listEntered=new java.util.concurrent.CountDownLatch(1),releaseList=new java.util.concurrent.CountDownLatch(1);volatile boolean holdList;
 ServerSocket server; volatile int logins=0,logouts=0,lists=0; boolean expire=true; String receivedRange=""; int downloadTaskRequests=0;String lastOtp="",lastSession="";int rejectLoginCode=403;boolean rejectLogins=false,dropAuthResponse=false;boolean passwordPosted=false;String userAgent="";
 @Before public void start() throws Exception {server=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));Thread worker=new Thread(()->{while(!server.isClosed())try(Socket socket=server.accept()){BufferedReader reader=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.UTF_8));String[] request=reader.readLine().split(" ");String query=request[1].contains("?")?request[1].substring(request[1].indexOf('?')+1):null;int length=0;String header;while((header=reader.readLine())!=null&&!header.isEmpty())if(header.toLowerCase().startsWith("content-length:"))length=Integer.parseInt(header.substring(15).trim());else if(header.toLowerCase().startsWith("user-agent:"))userAgent=header.substring(11).trim();else if(header.toLowerCase().startsWith("range:"))receivedRange=header.substring(6).trim();char[] chars=new char[length];int offset=0;while(offset<length){int count=reader.read(chars,offset,length-offset);if(count<0)break;offset+=count;}String body=new String(chars);Map<String,String> p=new HashMap<>();for(String part:(query==null?body:query).split("&")){String[] kv=part.split("=",2);if(kv.length==2)p.put(URLDecoder.decode(kv[0],"UTF-8"),URLDecoder.decode(kv[1],"UTF-8"));}String response;
 switch(p.getOrDefault("api","")){
 case "SYNO.API.Info":response="{\"success\":true,\"data\":{\"SYNO.API.Auth\":{\"path\":\"auth.cgi\"},\"SYNO.FileStation.List\":{\"path\":\"entry.cgi\"},\"SYNO.FileStation.Download\":{\"path\":\"entry.cgi\"},\"SYNO.DownloadStation.Task\":{\"path\":\"entry.cgi\",\"maxVersion\":1}}}";break;
 case "SYNO.API.Auth":if("logout".equals(p.get("method")))logouts++;if("login".equals(p.get("method"))){logins++;lastOtp=p.getOrDefault("otp_code","");lastSession=p.getOrDefault("session","");passwordPosted=request[0].equals("POST")&&query==null&&"secret".equals(p.get("passwd"));}if("login".equals(p.get("method"))&&dropAuthResponse)continue;response=rejectLogins&&"login".equals(p.get("method"))?"{\"success\":false,\"error\":{\"code\":"+rejectLoginCode+"}}":"{\"success\":true,\"data\":{\"sid\":\"private-session-"+logins+"\"}}";break;
 case "SYNO.DownloadStation.Task":downloadTaskRequests++;response="{\"success\":true,\"data\":{\"total\":0,\"tasks\":[]}}";break;
 case "SYNO.FileStation.List":if(holdList){listEntered.countDown();releaseList.await(6,java.util.concurrent.TimeUnit.SECONDS);}lists++;if(expire){expire=false;response="{\"success\":false,\"error\":{\"code\":106}}";}else if("0".equals(p.get("offset")))response="{\"success\":true,\"data\":{\"total\":3,\"files\":[{\"name\":\"A.mkv\",\"path\":\"/video/A.mkv\"},{\"name\":\"B.mkv\",\"path\":\"/video/B.mkv\"}]}}";else response="{\"success\":true,\"data\":{\"total\":3,\"files\":[{\"name\":\"C.mkv\",\"path\":\"/video/C.mkv\"}]}}";break;
 case "SYNO.FileStation.Download":if(p.getOrDefault("path","").endsWith(".json")){response="{\"event_id\":\"fixture-event\",\"title\":\"Magyar cím\"}";break;}byte[] video={2,3,4};socket.getOutputStream().write("HTTP/1.1 206 Partial Content\r\nContent-Type: video/x-matroska\r\nContent-Length: 3\r\nContent-Range: bytes 2-4/10\r\nConnection: close\r\n\r\n".getBytes(StandardCharsets.US_ASCII));socket.getOutputStream().write(video);continue;
 default:throw new IOException("Unexpected API");}
 byte[] b=response.getBytes(StandardCharsets.UTF_8);socket.getOutputStream().write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+b.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));socket.getOutputStream().write(b);}catch(Exception ignored){}});worker.start();}
 @After public void stop() throws Exception {releaseList.countDown();server.close();}
 NasClient client() throws Exception {NasClient c=new NasClient(new NasClient.Credentials("http://127.0.0.1:"+server.getLocalPort(),"","test","secret",""));c.connect();return c;}
 @Test public void renewsSessionAndReadsAllPages() throws Exception {NasClient c=client();assertEquals(3,c.list("/video").size());assertEquals(2,logins);assertEquals(3,lists);assertTrue(passwordPosted);assertEquals("SynoStreamAndroid/"+BuildConfig.VERSION_NAME,userAgent);}
 @Test public void preservesRangeAndOriginalBytes() throws Exception {try(NasClient.Stream stream=client().stream("/video/film.mkv","bytes=2-4",false)){assertEquals(206,stream.connection.getResponseCode());assertArrayEquals(new byte[]{2,3,4},stream.body.readAllBytes());}assertEquals("bytes=2-4",receivedRange);}
 @Test public void jsonFileContentIsReadable()throws Exception{assertEquals("Magyar cím",new org.json.JSONObject(new String(client().readFile("/video/.synostream/parositasok/test.json",65536),StandardCharsets.UTF_8)).getString("title"));}
 @Test public void onlyExplicitFailureEnvelopeIsAnError(){assertNull(NasClient.downloadFailure("{\"title\":\"A\"}".getBytes(StandardCharsets.UTF_8)));assertNull(NasClient.downloadFailure("not json".getBytes(StandardCharsets.UTF_8)));assertNotNull(NasClient.downloadFailure("{\"success\":false,\"error\":{\"code\":106}}".getBytes(StandardCharsets.UTF_8)));}
 @Test public void downloadsCloseKeepsAuthenticatedMainSession()throws Exception{NasClient c=client();int before=logins;DownloadStation ds=new DownloadStation(c,new TorrentRulesTest.Memory(),"fixture");ds.close();expire=false;c.list("/video");assertEquals(before,logins);}
}
